import numpy as np

def init_state(w):
    return {"m": np.zeros_like(w), "v": np.zeros_like(w), "t": 0}

def adam_step(w, g, st, lr=1e-3, b1=0.9, b2=0.999, eps=1e-8):
    st["t"] += 1
    st["m"] = b1 * st["m"] + (1 - b1) * g
    st["v"] = b2 * st["v"] + (1 - b2) * g * g
    m_hat = st["m"] / (1 - b1 ** st["t"])
    v_hat = st["v"] / (1 - b2 ** st["t"])
    return w - lr * m_hat / (np.sqrt(v_hat) + eps)

import numpy as np

def posterior(prior, lik):
    joint = np.asarray(prior) * np.asarray(lik)
    return joint / joint.sum()

def update(prior, lik_rows):
    post = np.asarray(prior, dtype=float)
    for lik in lik_rows:
        post = posterior(post, lik)
    return post

import numpy as np

def kfold_indices(n, k, seed=0):
    idx = np.random.RandomState(seed).permutation(n)
    folds = np.array_split(idx, k)
    for i in range(k):
        train = np.concatenate(folds[:i] + folds[i + 1:])
        yield train, folds[i]

def cross_val_score(fit, score, X, y, k=5, seed=0):
    out = []
    for tr, va in kfold_indices(len(X), k, seed):
        model = fit(X[tr], y[tr])
        out.append(score(model, X[va], y[va]))
    return np.array(out)

import numpy as np

def fit_scaler(X):
    return X.mean(0), X.std(0)

def transform(X, stats):
    mu, sd = stats
    return (X - mu) / sd

def split_then_scale(X, n_train):
    stats = fit_scaler(X[:n_train])
    tr, te = X[:n_train], X[n_train:]
    return transform(tr, stats), transform(te, stats)

def leaky_scale(X, n_train):
    Z = transform(X, fit_scaler(X))
    return Z[:n_train], Z[n_train:]

import numpy as np

def gini(y):
    p = np.bincount(y) / len(y)
    return 1 - p @ p

def grow(X, y, depth):
    best, leaf = (gini(y), None, None), np.bincount(y).argmax()
    if depth == 0 or best[0] == 0:
        return leaf
    for j in range(X.shape[1]):
        v = np.unique(X[:, j])
        for t in (v[:-1] + v[1:]) / 2:
            m = X[:, j] <= t
            s = m.mean() * gini(y[m]) + (1 - m.mean()) * gini(y[~m])
            if s < best[0] - 1e-12:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    m = X[:, j] <= t
    left = grow(X[m], y[m], depth - 1)
    return (j, t, left, grow(X[~m], y[~m], depth - 1))

def predict_one(tree, x):
    while isinstance(tree, tuple):
        j, t, left, right = tree
        tree = left if x[j] <= t else right
    return tree

import numpy as np

def dropout(x, p, rng, train=True):
    if not train or p == 0:
        return x, np.ones_like(x)
    keep = rng.random(x.shape) >= p
    mask = keep / (1 - p)
    return x * mask, mask

def dropout_backward(d_out, mask):
    return d_out * mask

import numpy as np

def entropy(p):
    p = p[p > 0]
    return -np.sum(p * np.log(p))

def cross_entropy(p, q):
    m = p > 0
    return -np.sum(p[m] * np.log(q[m]))

def kl(p, q):
    return cross_entropy(p, q) - entropy(p)

import numpy as np

def stump(X, r):
    best, n = (-1, 0, 0, 0, 0), np.arange(1, len(r))
    for j in range(X.shape[1]):
        o = np.argsort(X[:, j])
        x, c = X[o, j], np.cumsum(r[o])
        sl, sr = c[:-1], c[-1] - c[:-1]
        score = sl ** 2 / n + sr ** 2 / (len(r) - n)
        score[x[:-1] == x[1:]] = -1
        i = score.argmax()
        if score[i] > best[0]:
            t, nr = (x[i] + x[i + 1]) / 2, len(r) - n[i]
            best = (score[i], j, t, sl[i] / n[i], sr[i] / nr)
    return best[1:]

def fit(X, y, rounds=50, lr=0.1):
    pred, stumps = np.full(len(y), y.mean()), []
    for _ in range(rounds):
        j, t, a, b = stump(X, y - pred)
        pred += lr * np.where(X[:, j] <= t, a, b)
        stumps.append((j, t, a, b))
    return y.mean(), lr, stumps

def predict(model, X):
    f0, lr, stumps = model
    return f0 + lr * sum(np.where(X[:, j] <= t, a, b)
                         for j, t, a, b in stumps)

