import numpy as np

def kmeans(X, C, iters=100):
    for _ in range(iters):
        d = ((X[:, None] - C[None]) ** 2).sum(-1)
        lab = d.argmin(1)
        new = np.array([X[lab == j].mean(0) for j in range(len(C))])
        if np.allclose(new, C):
            break
        C = new
    return C, lab

