def fit(X, y, iters=25):
    A = np.c_[np.ones(len(X)), X]
    w = np.zeros(A.shape[1])
    for _ in range(iters):
        p = sigmoid(A @ w)
        g = A.T @ (p - y)
        H = (A.T * (p * (1 - p))) @ A
        w -= np.linalg.solve(H, g)
    return w

