import numpy as np

def fit(X, y):
    cs = np.unique(y)
    prior = np.array([(y == c).mean() for c in cs])
    mu = np.array([X[y == c].mean(0) for c in cs])
    var = np.array([X[y == c].var(0) for c in cs])
    return cs, prior, mu, var + 1e-9 * X.var(0).max()

def log_joint(model, X):
    cs, prior, mu, var = model
    d = (X[:, None, :] - mu) ** 2 / var
    ll = -0.5 * (np.log(2 * np.pi * var) + d).sum(2)
    return np.log(prior) + ll

def predict_proba(model, X):
    s = log_joint(model, X)
    p = np.exp(s - s.max(1, keepdims=True))
    return p / p.sum(1, keepdims=True)

