import numpy as np

def gini(y):
    p = np.bincount(y, minlength=2) / len(y)
    return 1 - p @ p

def grow(X, y, depth, m, rng):
    leaf = np.bincount(y, minlength=2).argmax()
    if depth == 0 or gini(y) == 0:
        return leaf
    best = (gini(y), None, None)
    for j in rng.choice(X.shape[1], m, replace=False):
        for t in np.unique(X[:, j])[:-1]:
            k = X[:, j] <= t
            s = k.mean() * gini(y[k]) + (1 - k.mean()) * gini(y[~k])
            if s < best[0]:
                best = (s, j, t)
    if best[1] is None:
        return leaf
    _, j, t = best
    k = X[:, j] <= t
    l = grow(X[k], y[k], depth - 1, m, rng)
    return (j, t, l, grow(X[~k], y[~k], depth - 1, m, rng))

def fit(X, y, B=25, depth=6, seed=0):
    rng = np.random.default_rng(seed)
    m = max(1, int(np.sqrt(X.shape[1])))
    trees = []
    for _ in range(B):
        i = rng.integers(0, len(X), len(X))
        trees.append(grow(X[i], y[i], depth, m, rng))
    return trees

def predict_one(trees, x):
    votes = []
    for tree in trees:
        while isinstance(tree, tuple):
            j, t, l, r = tree
            tree = l if x[j] <= t else r
        votes.append(tree)
    return int(np.mean(votes) > 0.5)

import numpy as np

def ridge(X, y, lam):
    xm, ym = X.mean(0), y.mean()
    Xc = X - xm
    A = Xc.T @ Xc + lam * np.eye(X.shape[1])
    w = np.linalg.solve(A, Xc.T @ (y - ym))
    return w, ym - xm @ w

def soft(z, t):
    return np.sign(z) * np.maximum(np.abs(z) - t, 0)

def lasso(X, y, lam, sweeps=500):
    xm, ym = X.mean(0), y.mean()
    Xc, r = X - xm, y - ym
    w = np.zeros(X.shape[1])
    for _ in range(sweeps):
        for j in range(len(w)):
            r += Xc[:, j] * w[j]
            z = Xc[:, j] @ r / len(r)
            w[j] = soft(z, lam) / (Xc[:, j] ** 2).mean()
            r -= Xc[:, j] * w[j]
    return w, ym - xm @ w

import numpy as np

def softmax(s):
    e = np.exp(s - s.max(axis=-1, keepdims=True))
    return e / e.sum(axis=-1, keepdims=True)

def self_attention(X, Wq, Wk, Wv, causal=False):
    Q, K, V = X @ Wq, X @ Wk, X @ Wv
    scores = Q @ K.T / np.sqrt(K.shape[-1])
    if causal:
        keep = np.tril(np.ones(scores.shape, dtype=bool))
        scores = np.where(keep, scores, -np.inf)
    A = softmax(scores)
    return A @ V, A

import numpy as np

def softmax(z):
    z = z - z.max(axis=1, keepdims=True)
    e = np.exp(z)
    return e / e.sum(axis=1, keepdims=True)

def cross_entropy(z, y):
    z = z - z.max(axis=1, keepdims=True)
    lse = np.log(np.exp(z).sum(axis=1))
    return (lse - z[np.arange(len(y)), y]).mean()

def grad_logits(z, y):
    p = softmax(z)
    p[np.arange(len(y)), y] -= 1
    return p / len(y)

import numpy as np

def fit(X, y, lam=0.01, iters=3000):
    # y must be in {-1, +1}
    w, b = np.zeros(X.shape[1]), 0.0
    for t in range(1, iters + 1):
        bad = y * (X @ w + b) < 1
        gw = lam * w - (y[bad, None] * X[bad]).sum(0) / len(y)
        gb = -y[bad].sum() / len(y)
        eta = 1 / (lam * (t + 10))
        w -= eta * gw
        b -= eta * gb
    return w, b

def predict(w, b, X):
    return np.sign(X @ w + b)
